//! The first four calls of device method 0x218 in a run (2026-11-25, main
//! at 22bf30c): settings, code and binding table, as logged.

use super::*;

fn hex(s: &str) -> Vec<u8> {
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
}

/// (settings, code, binding table) of call `n`.
const CALLS: [[&str; 3]; 4] = [
    [
        "00cf05400201096c00000000080008000100000043032c408a0b0000",
        "",
        "",
    ],
    [
        "00cf05400201096c00000000080008000100000043032c408a0b0000",
        "",
        "",
    ],
    [
        "00cf05400201096c00000000080008000100000043032c408a0b0000",
        "",
        "",
    ],
    [
        "00cf05400201096c00000000080008000100000045032c408a0b0000",
        "",
        "",
    ],
];

fn program(n: usize) -> crate::NativeProgram {
    let [settings, code, table] = CALLS[n].map(hex);
    let c = compute_container(&settings, &code, &table).unwrap();
    let c = crate::Container::parse(&c).unwrap();
    let mut programs = crate::native_programs(c.part(FourCC::DXIL).unwrap().data).unwrap();
    assert_eq!(programs.len(), 1);
    programs.remove(0)
}

/// The settings and binding table read as the code uses them: an 8x8
/// group, the table's address in user-data dword 4 (s4, `s_mov_b32 s8,
/// s4`), a texture at its dword 0, storage textures from dword 8, and the
/// constant buffer after them (`s_load_dwordx4 ... 0x40` in call 1).
#[test]
fn compute_calls_read_as_their_code_uses_them() {
    use crate::native::{ComputeIo, ResourceType, RootType, StageIo};
    let p = program(0);
    assert_eq!(p.stage, crate::HwStage::Cs);
    assert!(p.wave64);
    assert_eq!(p.vgprs, 16);
    assert_eq!(p.io, StageIo::Cs(ComputeIo { rsrc2: 0xb8a, threads: [8, 8, 1] }));
    assert_eq!(p.layout.len(), 1);
    let table = p.layout[0];
    assert_eq!((table.root, table.user_data, table.slot, table.sgprs), (RootType::Table, 4, 0, 1));
    let kinds: Vec<_> = p.used.iter().map(|u| (u.kind, u.root, u.table_offset_dwords, u.dwords)).collect();
    assert_eq!(
        kinds,
        [
            (ResourceType::Sampler, RootType::ImmediateSampler, 0, 4),
            (ResourceType::Srv, RootType::Table, 0, 8),
            (ResourceType::Uav, RootType::Table, 8, 8),
            (ResourceType::Cbv, RootType::Table, 16, 4),
        ]
    );
    for n in 1..4 {
        let p = program(n);
        assert_eq!(p.layout, [table]);
        assert!(p.used.iter().any(|u| u.kind == ResourceType::Cbv));
    }
}

/// Each of the four translates.
#[test]
fn compute_calls_translate() {
    for n in 0..4 {
        let [settings, code, table] = CALLS[n].map(hex);
        let c = compute_container(&settings, &code, &table).unwrap();
        if let Err(e) = crate::emit::translate(&c) {
            panic!("call {}: {e}", n + 1);
        }
    }
}
